// profileCache.ts
type Entry<T> = { value: T; expiresAt: number };

export class ProfileCache<T> {
  private entries = new Map<string, Entry<T>>();
  private inFlight = new Map<string, Promise<T>>();

  constructor(
    private fetchProfile: (userId: string) => Promise<T>,
    private ttlMs = 60_000,
    private maxEntries = 10_000,
  ) {}

  async get(userId: string): Promise<T> {
    const hit = this.entries.get(userId);
    if (hit && hit.expiresAt > Date.now()) {
      // re-insert to mark as most recently used
      this.entries.delete(userId);
      this.entries.set(userId, hit);
      return hit.value;
    }

    // concurrent misses share one upstream call
    const pending = this.inFlight.get(userId);
    if (pending) return pending;

    const request: Promise<T> = this.fetchProfile(userId)
      .then((value) => {
        // skip the write if invalidate() ran during the fetch
        if (this.inFlight.get(userId) === request) this.set(userId, value);
        return value;
      })
      .finally(() => {
        if (this.inFlight.get(userId) === request) this.inFlight.delete(userId);
      });
    this.inFlight.set(userId, request);
    return request;
  }

  invalidate(userId: string): void {
    this.entries.delete(userId);
    this.inFlight.delete(userId);
  }

  private set(userId: string, value: T): void {
    this.entries.delete(userId);
    this.entries.set(userId, { value, expiresAt: Date.now() + this.ttlMs });
    if (this.entries.size > this.maxEntries) {
      // Map iterates in insertion order, so the first key is least recently used
      const oldest = this.entries.keys().next().value;
      if (oldest !== undefined) this.entries.delete(oldest);
    }
  }
}
